    "chapter_number": 1,
    "verse_number": 3,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 1:3",
    "original_text": "اور خُدا نے کہا کہ روشنی ہو جا اور روشنی ہو گئی۔",
