    "book_id": "book-gen-1",
    "chapter_id": "chap-01-1",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 1,
    "verse_number": 4,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 1:4",
    "original_text": "اور خُدا نے کہاکہ روشنی اچھی ہے اور خُدا نے روشنی کو تاریکی سے جُدا کیا",
