    "chapter_number": 1,
    "verse_number": 12,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 1:12",
    "original_text": "اور گِرفتار ہوکر بابُل جانے کے بعد یکُونیاہ سے سیالتی ایل پَیدا ہُؤا اور سیالتی ایل سے زرُبّابُل پَیدا ہُؤا۔",
