    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 10:12",
    "original_text": "اور نیِنوہ اور کلح کے درمیان رؔسن جو بڑا شہر ہے بنایا۔",
