    "chapter_number": 10,
    "verse_number": 18,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 10:18",
    "original_text": "اور اروادی اورصمارمی اور حماتی پَیدا ہوئے اور بعد میں کنعانی قبیلے پھَیل گئے۔",
    "source_name": "WordPocket Urdu Bible",
