    "book_id": "book-gen-1",
    "chapter_id": "chap-01-10",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 10,
    "verse_number": 22,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 10:22",
    "original_text": "بنی سِؔم یہ ہیں ۔ عَیلام اور اؔسور اور ارفکَؔسداور لُودؔ اور ارؔام۔",
