    "chapter_id": "chap-01-10",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 10,
    "verse_number": 23,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 10:23",
    "original_text": "اور بنی ارؔام یہ ہیں ۔ عُوضؔ اور حُوؔ ل اور جتؔر اور مؔس۔",
