    "verse_number": 36,
    "book_name_english": "Luke",
    "book_name_urdu": "لُوقا",
    "reference": "Luke 3:36",
    "original_text": "اور وہ قِینان کا اور وہ ارفِکسد کا اور وہ سِم کا اور وہ نوح کا اور وہ لمک کا۔",
