    "chapter_number": 3,
    "verse_number": 37,
    "book_name_english": "Luke",
    "book_name_urdu": "لُوقا",
    "reference": "Luke 3:37",
    "original_text": "اور وہ متُوسلح کا اور وہ حنُوک کا اور وہ یارِد کا اور وہ مہلل ایل کا اور وہ قِینان کا۔",
