    "chapter_number": 3,
    "verse_number": 38,
    "book_name_english": "Luke",
    "book_name_urdu": "لُوقا",
    "reference": "Luke 3:38",
    "original_text": "اور وہ انُوس کا اور وہ سیت کا اور وہ آدم کا اور وہ خُدا کا تھا۔",
    "source_name": "WordPocket Urdu Bible",
