    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-1",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 1,
    "verse_number": 5,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 1:5",
    "original_text": "کہ تُم اُس میں ہوکر سب باتوں میں کلام اور عِلم کی ہر طرح کی دَولت سے دَولتمند ہو گئے ہو۔",
