    "chapter_id": "chap-46-1",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 1,
    "verse_number": 7,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 1:7",
    "original_text": "یہاں تک کہ تُم کِسی نعمت میں کم نہِیں اور ہمارے خُداوند یِسُوع مسِیح کے ظُہُور کے مُنتظِر ہو۔",
