    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-1",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 1,
    "verse_number": 18,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 1:18",
    "original_text": "کِیُونکہ صلِیب کا پیغام ہلاک ہونے والوں کے نزدِیک بے وُقُوفی ہے مگر ہم نِجات پانے والوں کے نزدِیک خُدا کی قُدرت ہے۔",
