    "book_id": "book-1thess-52",
    "chapter_id": "chap-52-5",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 5,
    "verse_number": 19,
    "book_name_english": "1 Thessalonians",
    "book_name_urdu": "۱ تھِسلُنیکیوں",
    "reference": "1 Thessalonians 5:19",
    "original_text": "رُوح کو نہ بُجھاؤ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/52/5.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
