    "book_id": "book-2thess-53",
    "chapter_id": "chap-53-3",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 16,
    "book_name_english": "2 Thessalonians",
    "book_name_urdu": "۲ تھِسلُنیکیوں",
    "reference": "2 Thessalonians 3:16",
    "original_text": "اب خُداوند جو اِطمینان کا چشمہ ہے آپ ہی تُم کو ہمیشہ اور ہر طرح سے اِطمینان بخشے۔ خُداوند تُم سب کے ساتھ رہے۔",
