    "book_id": "book-2tim-55",
    "chapter_id": "chap-55-4",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 4,
    "verse_number": 9,
    "book_name_english": "2 Timothy",
    "book_name_urdu": "۲ تیمِتھُیس",
    "reference": "2 Timothy 4:9",
    "original_text": "میرے پاس جلد آنے کی کوشِش کر۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/55/4.htm",
