    "book_id": "book-2tim-55",
    "chapter_id": "chap-55-4",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 4,
    "verse_number": 14,
    "book_name_english": "2 Timothy",
    "book_name_urdu": "۲ تیمِتھُیس",
    "reference": "2 Timothy 4:14",
    "original_text": "سِکندر ٹھٹھیرے نے مُجھ سے بہُت بُرائیاں کِیں۔ خُداوند اُسے اُس کے کاموں کے مُوافِق بدلہ دے گا۔",
