    "verse_number": 9,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 5:9",
    "original_text": "اِسی واسطے ہم یہ حَوصلہ رکھتے ہیں کہ وطن میں ہوں خواہ جلاوطن اُس کو خُوش کریں۔",
