    "book_id": "book-2cor-47",
    "chapter_id": "chap-47-8",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 8,
    "verse_number": 3,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 8:3",
    "original_text": "اور مَیں گواہی دیتا ہُوں کہ اُنہوں نے مقدُور کے مُوافِق بلکہ مقدُور سے بھی زِیادہ اپنی خُوشی سے دِیا۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/47/8.htm",
