    "book_id": "book-2cor-47",
    "chapter_id": "chap-47-8",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 8,
    "verse_number": 9,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 8:9",
    "original_text": "کِیُونکہ تُم ہمارے خُداوند یِسُوع مسِیح کے فضل کو جانتے ہو کہ وہ اگرچہ دَولتمند تھا مگر تُمہاری خاطِر غرِیب بن گیا تاکہ تُم اُس کی غرِیبی کے سبب سے دَولتمند ہو جاؤ۔",
