    "book_id": "book-2cor-47",
    "chapter_id": "chap-47-8",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 8,
    "verse_number": 11,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 8:11",
    "original_text": "پَس اَب اِس کام کو پُورا بھی کرو تاکہ جَیسے تُم اِرادہ کرنے میں مُستعِد تھے وَیسے ہی مقدُور کے مُوافِق تکمِیل بھی کرو۔",
