    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 8,
    "verse_number": 12,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 8:12",
    "original_text": "کِیُونکہ اگر نِیّت ہو تو خَیرات اُس کے مُوافِق مقبُول ہو گی جو آدمِی کے پاس ہے نہ اُس کے مُوافِق جو اُس کے پاس نہِیں۔",
