    "book_id": "book-2cor-47",
    "chapter_id": "chap-47-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 8,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 11:8",
    "original_text": "مَیں نے اَور کلِیسیاؤں کو لُوٹا یعنی اُن سے اُجرت لی تاکہ تُمہاری خِدمت کرُوں۔",
