    "book_id": "book-2cor-47",
    "chapter_id": "chap-47-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 10,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 11:10",
    "original_text": "مسِیح کی صداقت کی قَسم جو مُجھ میں ہے۔ اخَیہ کے علاقہ میں کوئی شَخص مُجھے یہ فخر کرنے سے نہ روکے گا۔",
