    "book_id": "book-2cor-47",
    "chapter_id": "chap-47-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 13,
    "book_name_english": "2 Corinthians",
    "book_name_urdu": "۲ کُرنتھِیوں",
    "reference": "2 Corinthians 11:13",
    "original_text": "کِیُونکہ اَیسے لوگ جھُوٹے رَسُول اور دغابازی سے کام کرنے والے ہیں اور اپنے آپ کو مسییح کے رَسُولوں کے ہمشکل بنا لیتے ہیں۔",
