    "verse_number": 11,
    "book_name_english": "Romans",
    "book_name_urdu": "رومیوں",
    "reference": "Romans 3:11",
    "original_text": "کوئی سَمَجھ دار نہِیں کوئی خُدا کا طالِب نہِیں۔",
    "source_name": "WordPocket Urdu Bible",
