    "book_id": "book-rom-45",
    "chapter_id": "chap-45-3",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 12,
    "book_name_english": "Romans",
    "book_name_urdu": "رومیوں",
    "reference": "Romans 3:12",
    "original_text": "سب گُمراہ ہیں سب کے سب نِکمّے بن گئے۔ کوئی بھلائی کرنے والا نہِیں۔ ایک بھی نہِیں۔",
    "source_name": "WordPocket Urdu Bible",
