    "book_id": "book-rom-45",
    "chapter_id": "chap-45-3",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 15,
    "book_name_english": "Romans",
    "book_name_urdu": "رومیوں",
    "reference": "Romans 3:15",
    "original_text": "اُن کے قدم خُون بہانے کے لِئے تیز رَو ہیں۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/45/3.htm",
