    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 15,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 3:15",
    "original_text": "اور جِس کا کام جل جائے گا وہ نُقصان اُٹھائے گا لیکِن خُود بچ جائے گا مگر جلتے جلتے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/46/3.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
