    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-10",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 10,
    "verse_number": 6,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 10:6",
    "original_text": "یہ باتیں ہمارے واسطے عِبرت ٹھہریں تاکہ ہم بُری چِیزوں کی خواہِش نہ کریں جَیسے اُنہوں نے کی۔",
