    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-10",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 10,
    "verse_number": 8,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 10:8",
    "original_text": "اور ہم حرامکاری نہ کریں جِس طرح اُن میں سے بعض نے کی اور ایک ہی دِن میں تیِئیس ہزار مارے گئے۔",
