    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-10",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 10,
    "verse_number": 32,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 10:32",
    "original_text": "تُم نہ یہُودِیوں کے لِئے ٹھوکر کا باعِث بنو نہ یُونانِیوں کے لِئے نہ خُدا کی کلِیسیا کے لِئے۔",
