    "chapter_number": 11,
    "verse_number": 10,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 11:10",
    "original_text": "پَس فرِشتوں کے سبب سے عَورت کو چاہئے کہ اپنے سر پر محکُوم ہونے کی علامت رکھّے۔",
