    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 12,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 11:12",
    "original_text": "کِیُونکہ جَیسے عَورت مرد سے ہے وَیسے ہی مرد بھی عَورت کے وسِیلہ سے ہے مگر سب چِیزیں خُدا کی طرف سے ہیں۔",
