    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 14,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 11:14",
    "original_text": "کیا تُم کو طبعی طَور پر بھی معلُوم نہِیں کہ اگر مرد لمبے بال رکھّے تو اُس کی بے حُرمتی ہے؟",
