    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-15",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 15,
    "verse_number": 14,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 15:14",
    "original_text": "اور اگر مسِیح نہِیں جی اُٹھا تو ہماری منادی بھی بےفائِدہ ہے اور تُمہارا اِیمان بھی بےفائِدہ۔",
