    "chapter_number": 15,
    "verse_number": 15,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 15:15",
    "original_text": "بلکہ ہم خُدا کے جھُوٹے گواہ ٹھہرے کِیُونکہ ہم نے خُدا کے بابت یہ گواہی دی کہ اُس نے مسِیح کو جِلا دِیا حالانکہ نہِیں جِلایا اگر بِالفرض مُردے نہِیں جی اُٹھتے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/46/15.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
