    "book_id": "book-1cor-46",
    "chapter_id": "chap-46-15",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 15,
    "verse_number": 25,
    "book_name_english": "1 Corinthians",
    "book_name_urdu": "۱ کُرنتھِیوں",
    "reference": "1 Corinthians 15:25",
    "original_text": "کِیُونکہ جب تک کہ وہ سب دُشمنوں کو اپنے پاؤں تَلے نہ لے آئے اُس کو بادشاہی کرنا ضرُور ہے۔",
