    "book_id": "book-rev-66",
    "chapter_id": "chap-66-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 6,
    "book_name_english": "Revelation",
    "book_name_urdu": "مُکاشفہ",
    "reference": "Revelation 7:6",
    "original_text": "آشر کے قبِیلہ میں سے بارہ ہزار پر۔ نفتالی کے قبِیلہ میں سے بارہ ہزار پر۔ منسّی کے قبِیلہ میں سے بارہ ہزار پر۔",
    "source_name": "WordPocket Urdu Bible",
