    "verse_number": 6,
    "book_name_english": "John",
    "book_name_urdu": "یُوحنّا",
    "reference": "John 10:6",
    "original_text": "یِسُوع نے اُن سے یہ تَمثِیل کہی لیکِن وہ نہ سَمَجھے کہ یہ کیا باتیں ہیں جو ہم سے کہتا ہے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/43/10.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
