    "book_id": "book-matt-40",
    "chapter_id": "chap-40-4",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 4,
    "verse_number": 2,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 4:2",
    "original_text": "اور چالیس دِن اور چالیس رات فاقہ کر کے آخر کو اُسے بھُوک لگی۔",
