    "book_id": "book-matt-40",
    "chapter_id": "chap-40-5",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 5,
    "verse_number": 3,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 5:3",
    "original_text": "مُبارک ہیں وہ جو دِل کے غریب ہیں کِیُونکہ آسمان کی بادشاہی اُن ہی کی ہے۔",
    "source_name": "WordPocket Urdu Bible",
