    "book_id": "book-matt-40",
    "chapter_id": "chap-40-5",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 5,
    "verse_number": 7,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 5:7",
    "original_text": "مُبارک ہیں وہ جو رحمدِل ہیں کِیُونکہ اُن پر رحم کِیا جائے گا۔",
