    "book_id": "book-matt-40",
    "chapter_id": "chap-40-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 11,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 6:11",
    "original_text": "ہمارے روز کی روٹی آج ہمیں دے۔",
