    "book_id": "book-matt-40",
    "chapter_id": "chap-40-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 12,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 6:12",
    "original_text": "اور جِس طرح ہم نے اپنے قرضداروں کو مُعاف کِیا ہے تُو بھی ہمارے قرض ہمیں مُعاف کر۔",
