    "book_id": "book-matt-40",
    "chapter_id": "chap-40-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 13,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 6:13",
    "original_text": "اور ہمیں آزمایش میں نہ لا بلکہ بُرائی سے بَچا [کِیُونکہ بادشاہی اور قُدرت اور جلال ہمیشہ تیرے ہی ہیں۔ آمین]",
    "source_name": "WordPocket Urdu Bible",
