    "verse_number": 33,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 10:33",
    "original_text": "مگر جو کوئی آدمِیوں کے سامنے میرا اِنکار کرے گا میں بھی اپنے باپ کے سامنے جو آسمان پر ہے اُس کا اِنکار کرُوں گا۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/40/10.htm",
