    "book_id": "book-matt-40",
    "chapter_id": "chap-40-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 14,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 11:14",
    "original_text": "اور چاہو تو مانو۔ ایلِیاہ جو آنے والا تھا یِہی ہے۔",
    "source_name": "WordPocket Urdu Bible",
