    "book_id": "book-matt-40",
    "chapter_id": "chap-40-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 15,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 11:15",
    "original_text": "جِس کے سُننے کے کان ہوں وہ سُن لے۔",
