    "verse_number": 21,
    "book_name_english": "Matthew",
    "book_name_urdu": "متّی",
    "reference": "Matthew 17:21",
    "original_text": "[ لیکِن یہ قِسم دُعا کے سِوا اور کِسی طرح نہِیں نِکل سکتی]",
