    "book_id": "book-gen-1",
    "chapter_id": "chap-01-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 8,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 11:8",
    "original_text": "پس خُداوند نے اُنکو وہاں سے تمام رُویِ زمین پر پراگندہ کِیا سو وہ اُس شہر کے بانے سے باز آئے۔",
