    "book_id": "book-gen-1",
    "chapter_id": "chap-01-17",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 17,
    "verse_number": 27,
    "book_name_english": "Genesis",
    "book_name_urdu": "پیَدایش",
    "reference": "Genesis 17:27",
    "original_text": "اور اُسکے گھر کے سب مردوں کا ختنہ خانہ زادوں اور اُنکا بھی جو پردیسیوں سے خریدے گئے تھے اُسکے ساتھ ہُوا۔",
