    "book_name_english": "Leviticus",
    "book_name_urdu": "احبار",
    "reference": "Leviticus 5:19",
    "original_text": "یہ جرم کی قربانی ہے کیونکہ وہ یقینأ خداوند کے آگے جمرم ہے۔",
