    "book_id": "book-lev-3",
    "chapter_id": "chap-03-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 23,
    "book_name_english": "Leviticus",
    "book_name_urdu": "احبار",
    "reference": "Leviticus 11:23",
    "original_text": "پر سب پردار رینگنے والے جاندار جنکے چار پاؤں ہیں وہتمہارے لئے مکروہ ہیں۔",
