    "book_id": "book-num-4",
    "chapter_id": "chap-04-2",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 2,
    "verse_number": 17,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
