    "book_id": "book-num-4",
    "chapter_id": "chap-04-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 20,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 7:20",
    "original_text": "دس مثقال سونے کا ایک چمچ جو بخور سے بھرا تھا",
