    "verse_number": 21,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 7:21",
    "original_text": "سو ختنی قربانی کے لیے ایک بچھڑا ایک مینڈھا اور ایک نر یکسالہ برہ",
