    "chapter_id": "chap-04-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 45,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 7:45",
    "original_text": "سوختنی قربانی کے لیے ایک بچھڑا ایک مینڈھا ایک نر یکسالہ برہ",
