    "verse_number": 70,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 7:70",
    "original_text": "خطا کی قربانی کے لیے ایک بکرا۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/04/7.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
