    "verse_number": 72,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 7:72",
    "original_text": "اور گیارہویں دن عکران کے بیٹے فجعی ایل نے جو آشر کے قبیلہ کا سردار تھا اپنا ہدیہ گذرانا",
