    "chapter_number": 13,
    "verse_number": 9,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 13:9",
    "original_text": "اور بنیمین کے قبیلہ سے رفو کا بیٹا فلتی",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/04/13.htm",
