    "chapter_number": 13,
    "verse_number": 10,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 13:10",
    "original_text": "اور زبولون کے قبیلہ سے سودی کا بیٹا جدی ایل",
