    "verse_number": 13,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 13:13",
    "original_text": "اور آشر کے قبیلہ سے میکا ایل کا بیٹا ستور",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/04/13.htm",
