    "book_id": "book-num-4",
    "chapter_id": "chap-04-29",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 29,
    "verse_number": 16,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
