    "chapter_number": 33,
    "verse_number": 19,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 33:19",
    "original_text": "رتمہ سے روانہ ہو کر رمون فارص میں خیمے کھڑے کیے",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/04/33.htm",
