    "book_id": "book-num-4",
    "chapter_id": "chap-04-33",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 33,
    "verse_number": 21,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 33:21",
    "original_text": "اور لبناہ سے کوچ کر کے ریسہ میں ڈیرے ڈالے",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/04/33.htm",
