    "id": "verse-04-33-23",
    "book_id": "book-num-4",
    "chapter_id": "chap-04-33",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 33,
    "verse_number": 23,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 33:23",
    "original_text": "اور قہیلاتہ سے چل کر کوہ سافر میں ڈیرا کیا۔",
