    "book_id": "book-num-4",
    "chapter_id": "chap-04-33",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 33,
    "verse_number": 24,
    "book_name_english": "Numbers",
    "book_name_urdu": "گنتی",
    "reference": "Numbers 33:24",
    "original_text": "کوہ سافت سے کوچ کر کے حرادہ میں میں خیمہ زن ہوئے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/04/33.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-14T07:59:13.179Z",
    "updated_at": "2026-09-14T07:59:13.179Z"
