    "chapter_number": 11,
    "verse_number": 20,
    "book_name_english": "Deuteronomy",
    "book_name_urdu": "استثنا",
    "reference": "Deuteronomy 11:20",
    "original_text": "اور تُو اِنکو اپنے گھر کی چوکٹھوں پر اور اپنے پھاٹکوں پر لکھاکرنا ۔",
