    "book_id": "book-deut-5",
    "chapter_id": "chap-05-14",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 14,
    "verse_number": 17,
    "book_name_english": "Deuteronomy",
    "book_name_urdu": "استثنا",
    "reference": "Deuteronomy 14:17",
    "original_text": "اور حواصل اور خم اور ہڑگیلا ۔",
    "source_name": "WordPocket Urdu Bible",
