    "verse_number": 40,
    "book_name_english": "Joshua",
    "book_name_urdu": "یشوؔع",
    "reference": "Joshua 19:40",
    "original_text": "اور ساتواں قرعہ بنی دان کے قبیلہ کے لئے انکے گھرانوں کے موافق نکلا۔ ا",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/06/19.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
