    "book_id": "book-josh-6",
    "chapter_id": "chap-06-19",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 19,
    "verse_number": 43,
    "book_name_english": "Joshua",
    "book_name_urdu": "یشوؔع",
    "reference": "Joshua 19:43",
    "original_text": "اور ایلون اور تمناتہ اور عقرون ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/06/19.htm",
