    "verse_number": 44,
    "book_name_english": "Joshua",
    "book_name_urdu": "یشوؔع",
    "reference": "Joshua 19:44",
    "original_text": "اور التقیہ اور جنتتون اور بعلات ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/06/19.htm",
