    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 23,
    "verse_number": 28,
    "book_name_english": "2 Samuel",
    "book_name_urdu": "2سموئیل",
    "reference": "2 Samuel 23:28",
    "original_text": "اخوحی ضؔلمون۔ نطوفاتی مہرؔی۔",
