    "book_id": "book-2sam-10",
    "chapter_id": "chap-10-23",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 23,
    "verse_number": 32,
    "book_name_english": "2 Samuel",
    "book_name_urdu": "2سموئیل",
    "reference": "2 Samuel 23:32",
    "original_text": "سعلبونی اؔلیخبہ بنی یسین یُونتؔن ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/10/23.htm",
