    "book_id": "book-1kgs-11",
    "chapter_id": "chap-11-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 10,
    "book_name_english": "1 Kings",
    "book_name_urdu": "1۔ سلاطِین",
    "reference": "1 Kings 6:10",
    "original_text": "اور اُس نے اُس پورے گھر سے لگی ہوئی پانچ پانچ ہاتھ اوُنچی منزلیں بنائیں اور وہ دیوار کی لکڑیوں کے سہارے اُس گھر پر ٹِکی ہوئی تھیں ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/11/6.htm",
