    "verse_number": 13,
    "book_name_english": "1 Kings",
    "book_name_urdu": "1۔ سلاطِین",
    "reference": "1 Kings 6:13",
    "original_text": "اور مَیں بنی اسرائیل کے درمیان رہونگا اور اپنی قوم اسرائیل کو ترک نہ کرونگا ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/11/6.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
