    "chapter_number": 14,
    "verse_number": 30,
    "book_name_english": "1 Kings",
    "book_name_urdu": "1۔ سلاطِین",
    "reference": "1 Kings 14:30",
    "original_text": "اور رحبعام اور یُربعام میں برابر جنگ رہی ۔",
