    "book_id": "book-1kgs-11",
    "chapter_id": "chap-11-15",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 15,
    "verse_number": 1,
    "book_name_english": "1 Kings",
    "book_name_urdu": "1۔ سلاطِین",
    "reference": "1 Kings 15:1",
    "original_text": "اور نباط کے بیٹے یُربعام کی سلطنت کے اٹھارویں سال سے ابیام یہوداہ پر سلطنت کرنے لگا ۔",
    "source_name": "WordPocket Urdu Bible",
