    "book_id": "book-2kgs-12",
    "chapter_id": "chap-12-16",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 16,
    "verse_number": 1,
    "book_name_english": "2 Kings",
    "book_name_urdu": "2 سلاطین",
    "reference": "2 Kings 16:1",
    "original_text": "اور رملیاہ کے بیٹے فقح کے سترھویں برس سے شاہِ یہوداہ یوتام کا بیٹا آخز سلطنت کرنے لگا",
