    "book_id": "book-1chr-13",
    "chapter_id": "chap-13-2",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 2,
    "verse_number": 13,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 2:13",
    "original_text": "یسّی سے اُسکا پہلوٹھا اِلیاب پیدا ہوا اور ابینداب دُوسرا اور سمع تیسرا۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/13/2.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
