    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 2:14",
    "original_text": "نتنی ایل چَوتھا ۔ رَدی پانچواں ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/13/2.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
