    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 2:39",
    "original_text": "اور خلصؔ پیدا ہوا اور خلصؔ پیدا ہوا اور خلص سے اِلعاصہ پیدا ہوا۔",
