    "verse_number": 11,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 4:11",
    "original_text": "اور سُخہ کے بھائی کلوب سے محؔیر پیدا ہُوا جو اِستون کا باپ تھا ۔",
    "source_name": "WordPocket Urdu Bible",
