    "verse_number": 12,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 6:12",
    "original_text": "اور اخیطوب سے صدوُق پیدا ہُوا اور صدُوق سے سلوم پیدا ہوُا ۔",
