    "book_id": "book-1chr-13",
    "chapter_id": "chap-13-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 14,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 6:14",
    "original_text": "اور عزریاہ سے سِرایاہ پیدا ہُوا اور سرِایا ہ سے یہوصؔدق پیدا ہُوا ۔",
    "source_name": "WordPocket Urdu Bible",
