    "book_id": "book-1chr-13",
    "chapter_id": "chap-13-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 27,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 6:27",
    "original_text": "نحت کا بیٹا اِلیاب ۔ اِلیاب کا بیٹا یروحام یروحام کا بیٹا اِلقانہ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/13/6.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T05:09:43.818Z",
    "updated_at": "2026-09-15T05:09:43.818Z"
