    "book_id": "book-1chr-13",
    "chapter_id": "chap-13-6",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 6,
    "verse_number": 65,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 6:65",
    "original_text": "اور اُنہوں نے بنی یُہوداہ کے قبیلہ اور بنی شمعون کے قبیلہ اور بنی بینمین کے قبیلہ میں سے یہ شہر جنکے نام مذکوُرہ ہُوئے قُرعہ ڈالکر دِئے۔",
