    "source_url": "https://wordpocket.com/lang_texts/ur/13/6.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T05:09:43.818Z",
    "updated_at": "2026-09-15T05:09:43.818Z"
