    "book_id": "book-1chr-13",
    "chapter_id": "chap-13-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 27,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 7:27",
    "original_text": "الیسمع کا بیٹا نون ۔ نون کا بیٹا یہوسُوع۔",
