    "chapter_id": "chap-13-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 31,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 7:31",
    "original_text": "اور بریعہ کے بیٹے حبر اور برزاویت کا باپ ملکی ؔ ایل تھے ۔",
