    "verse_number": 1,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 8:1",
    "original_text": "اور بینمین سے اُسکا پہلوٹھا بالع پیدا ہوا ۔ دُوسرا اشبیل تیسرا اخرؔخ ۔",
