    "chapter_number": 8,
    "verse_number": 2,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 8:2",
    "original_text": "چوتھا نُوحہ اور پانچواں ۔",
