    "source_url": "https://wordpocket.com/lang_texts/ur/13/8.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T05:09:44.703Z",
    "updated_at": "2026-09-15T05:09:44.703Z"
