    "chapter_id": "chap-13-24",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 24,
    "verse_number": 25,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 24:25",
    "original_text": "میکاہ کا بھائی یّسیاہ بنی یسّیاہ میں سے زکریاہ ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/13/24.htm",
