    "verse_number": 12,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 25:12",
    "original_text": "پانچویں نتنیاہ کو۔ اُسکے بیٹے اور بھائی اُس سمیت بارہ تھے۔",
    "source_name": "WordPocket Urdu Bible",
