    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 25:14",
    "original_text": "ساتویں یسری لاہ کو۔ اُسکے بیٹے اور بھائی اُس سمیت بارہ تھے۔",
