    "book_id": "book-1chr-13",
    "chapter_id": "chap-13-25",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 25,
    "verse_number": 15,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 25:15",
    "original_text": "آتھویں یسعیاہ کو ۔ اُسکے بیٹے اور بھائی اُس سمیت بارہ تھے۔",
