    "verse_number": 25,
    "book_name_english": "1 Chronicles",
    "book_name_urdu": "1۔تواریخ",
    "reference": "1 Chronicles 25:25",
    "original_text": "اٹھارھویں حنانی کو۔ اُسکے بیٹے اور بھائی اُس سمیت بارہ تھے۔",
