    "verse_number": 4,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 4:4",
    "original_text": "اور وہ بارہ بیلوں پر دھرا ہوا تھا۔ تین کا رُخ شِمال کی طرف اور تین کا رُخ مغرب کی طرف اور تین کا رُخ جنوب کی طرف اور تتین کا رُخ مشرق کی طرف تھا اور و بڑا حَوض اُن کے اُوپر تھا اور اُن سب کے پچھلے اعضا اندر کے رُخ تھے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/14/4.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T05:14:24.152Z",
    "updated_at": "2026-09-15T05:14:24.152Z"
