    "book_id": "book-2chr-14",
    "chapter_id": "chap-14-4",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 4,
    "verse_number": 9,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 4:9",
    "original_text": "اور اُس نے کاہنوں کا صحن اور بڑا صحن اور اُس صحن کے دروازوں کو بنایا اور اُن کے کِواڑوں کو پیتل سے منڈھا ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/14/4.htm",
