    "book_id": "book-2chr-14",
    "chapter_id": "chap-14-4",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 4,
    "verse_number": 10,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 4:10",
    "original_text": "اور اُس نے اُس بڑے حَوض کو مشرق کی طرف دہنے ہاتھ جنوبی رُخ پر رکھا۔",
