    "book_id": "book-2chr-14",
    "chapter_id": "chap-14-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 5,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 11:5",
    "original_text": "اور رحبعام یروشلیم میں رہنے لگا اور اُس نے یہوداہ میں حفاظت کے لیئے شہر بنائے۔",
