    "chapter_id": "chap-14-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 13,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 11:13",
    "original_text": "اور کاہن اور لاوی جو سارے اسرائیل میں تھے اپنی اپنی سرحد سے نکل کر اُس کے پاس آگئے۔",
