    "verse_number": 21,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 13:21",
    "original_text": "لیکن ابیاہ قوی ہوگیا اور اُس نے چودہ بیویاں بیاہیں اور اُس سے بائیس بیٹے اور سولہ بیٹیاں پیدا ہوئیں ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/14/13.htm",
