    "chapter_number": 17,
    "verse_number": 13,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 17:13",
    "original_text": "اور یہوداہ کے شہروں میں اُس کے بُہت سے کاروبار اور یروشلیم میں اُس کے جنگی مرد یعنی زبردست سورما تھے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/14/17.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T05:14:36.460Z",
