    "book_id": "book-2chr-14",
    "chapter_id": "chap-14-17",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 17,
    "verse_number": 15,
    "book_name_english": "2 Chronicles",
    "book_name_urdu": "2۔توارِیخ",
    "reference": "2 Chronicles 17:15",
    "original_text": "اور اُس سے دوسرے درجہ پر سردار یہو حنان اور اُس کے ساتھ دو لاکھ اسَی ہزار ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/14/17.htm",
