    "verse_number": 9,
    "book_name_english": "Ezra",
    "book_name_urdu": "عزرا",
    "reference": "Ezra 8:9",
    "original_text": "اور بنی یوآب میں سے عبدیاہ بن یحی ایل اور اس کے ساتھ دو سو اٹھارہ مرد۔",
    "source_name": "WordPocket Urdu Bible",
