    "verse_number": 5,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 3:5",
    "original_text": "اور ان سے آگے تقوعیوں نے مرمت کی پر انکے اسیروں نے اپنے مالک کے کام کے لئے گردن نہ جھکائی ۔",
