    "verse_number": 21,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 4:21",
    "original_text": "یوں ہم کام کرتے رہے اور اُن میں سے آدھے لوگ پوپھٹنے کے وقت سے تاروں کے دکھائی دینے تک برچھیاں لئے رہتے تھے۔",
