    "chapter_number": 5,
    "verse_number": 1,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 5:1",
    "original_text": "پھر لوگوں اور اُنکی بیویوں کی طرف سے اُنکے یہودی بھائیوں پر بڑی شکایت ہوئی۔",
