    "book_id": "book-neh-16",
    "chapter_id": "chap-16-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 57,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 7:57",
    "original_text": "سُلیمان کے خادموں کی اَولاد بنی سُوتی بنی سوفرت بنی فریدا ۔",
