    "verse_number": 13,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:13",
    "original_text": "اور اُسکے بھائی آبائی خاندانوں کے رئیس دو سو بیالیس اور امشی بن عزرایل بن اخسی بن مسیلموت بن اِمیر۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/16/11.htm",
