    "verse_number": 14,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:14",
    "original_text": "اور اُنکے بھائی زبردست سُورما ایک سو اٹھائیس اور اُنکا سردار زبدی ایل بن ہجدولیم تھا۔",
