    "chapter_number": 11,
    "verse_number": 17,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:17",
    "original_text": "اور متنیاہ بن میکا بن زبدی بن آسف سردار تھا جو دُعا کے وقت شُکرگذاری شُروع کرنے میں پیشوا تھا اور بقبوقیاہ اُسکے بھائیوں میں سے دُوسرے درجہ پر تھا اور عبدابن سموع بن جلال بن یدوتون۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/16/11.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T05:25:56.876Z",
    "updated_at": "2026-09-15T05:25:56.876Z"
