    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 20,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:20",
    "original_text": "اور اِسرائیلیوں اور کاہنوں اور لاویوں کے باقی لوگ یہوادہ کے سب شہروں میں اپنی اپنی ملکیت میں رہتے تھے۔",
