    "verse_number": 21,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:21",
    "original_text": "پر نتنیم عوفل میں بسے ہوئے تھے اور ضیحا اور جسفا نتنیم پر مُقرر تھے۔",
