    "book_id": "book-neh-16",
    "chapter_id": "chap-16-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 23,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:23",
    "original_text": "کیونکہ اُنکی بابت بادشاہ کی طرف سے حکم ہو چکا تھا اور گانے والوں کے لئے ہر روز کی ضرورت کے مطابق مُقررہ رسد تھی ۔",
