    "verse_number": 24,
    "book_name_english": "Nehemiah",
    "book_name_urdu": "نحمیاہ",
    "reference": "Nehemiah 11:24",
    "original_text": "اور فتحیاہ بن مشیزبیل جوزارح بن یہوداہ کی اَولاد میں سے تھا رعیت کے سب مُعاملات کے لئے بادشاہ کے حضور رہتا تھا۔",
