    "book_id": "book-ezek-26",
    "chapter_id": "chap-26-3",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 11,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 3:11",
    "original_text": "اب اٹھ اسیروں یعنی اپنی قوم کے لوگوں کے پاس جا اور ان سے کہہ خداوند خدا یوں فرماتا ہے خواہ وہ سنیں خواہ نہ سنیں۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/26/3.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T15:43:14.615Z",
