    "book_id": "book-ezek-26",
    "chapter_id": "chap-26-3",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 13,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 3:13",
    "original_text": "اور جانداروں کے پروں کے آیک دوسرے سے لگنے کی آواز اور ان کے مقابل پہیوں کی آواز اور ایک بڑے دھڑاکے کی آواز سنائی دی۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/26/3.htm",
