    "book_id": "book-ezek-26",
    "chapter_id": "chap-26-3",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 3,
    "verse_number": 14,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 3:14",
    "original_text": "اور روح مجھے اٹھا کر لے گئی۔ سو میں تلخ دل اور غضبناک ہو کر روانہ ہوا اور خداوند کا ہاتھ مجھ پر غالب تھا۔",
    "source_name": "WordPocket Urdu Bible",
