    "book_id": "book-ezek-26",
    "chapter_id": "chap-26-7",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 7,
    "verse_number": 5,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 7:5",
    "original_text": "خداوند خدا یوں فرماتا ہے کہ ایک بلا یعنی بلایِ عظیم ! دیکھ وہ آتی ہے۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/26/7.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
