    "book_id": "book-ezek-26",
    "chapter_id": "chap-26-9",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 9,
    "verse_number": 10,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 9:10",
    "original_text": "پس میری آنکھ رعایت نہ کرے گی اور میں ہرگز رحم نہ کروں گا۔ میں ان کی روش کا بدلہ ان کے سر پر لاﺅں گا۔",
