    "verse_number": 3,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 10:3",
    "original_text": "جب وہ شخص اندر گیا تب وہ کروبی ہیکل کے اندر کھڑے تھے اور اندرونی صحن بادل سے بھر گیا۔",
