    "book_id": "book-ezek-26",
    "chapter_id": "chap-26-11",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 11,
    "verse_number": 8,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 11:8",
    "original_text": "تم تلوار سے ڈرے ہو اور خداوند خدا یوں فرماتا ہے کہ میں تلوار تم پر لاﺅں گا۔",
