    "verse_number": 31,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 34:31",
    "original_text": "اور تم اے میری بھےڑو میری چراہ گاہ کی بھےڑ و ہو اور میں تمہارا خدا ہوں خداوند خدا فرماتا ہے۔",
