    "verse_number": 3,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 38:3",
    "original_text": "اور کہہ خداوند خدا یوں فرماتا ہے کہ دیکھ اے جوج روش اور مسک اور توبل کے فرمانروا میں تےرا مخالف ہوں ۔",
