    "verse_number": 22,
    "book_name_english": "Ezekiel",
    "book_name_urdu": "حزقی ایل",
    "reference": "Ezekiel 38:22",
    "original_text": "اور میں وبا بھیج کر اور خونریزی کر کے اسے سزا دونگا اور اس پر اور اس کے لشکروں پر اور ان بہت سے لوگوں پر جو اس کے ساتھ ہیں شدت کا مینہ اور بڑے بڑے اولے اور آگ اور گندھک برساﺅنگا ۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/26/38.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
    "created_at": "2026-09-15T15:43:33.386Z",
    "updated_at": "2026-09-15T15:43:33.386Z"
