    "verse_number": 11,
    "book_name_english": "Micah",
    "book_name_urdu": "میکاہ",
    "reference": "Micah 7:11",
    "original_text": "تیری فصیل کی تعمیر کے روز تیری حُدود بڑھائی جائیں گی۔",
    "source_name": "WordPocket Urdu Bible",
    "source_url": "https://wordpocket.com/lang_texts/ur/33/7.htm",
    "translation": "WordPocket Urdu Bible",
    "language": "ur",
