    "book_id": "book-zech-38",
    "chapter_id": "chap-38-4",
    "translation_id": "trans-wordpocket-ur",
    "chapter_number": 4,
    "verse_number": 14,
    "book_name_english": "Zechariah",
    "book_name_urdu": "زکریاہ",
    "reference": "Zechariah 4:14",
    "original_text": "اُس نے کہا یہ وہ مُمسوح ہیں جو ربُ العالمین کے حضور کھڑے رہتے ہیں۔",
